import * as T from './vendor/three.js';
const priority=r=>({primary:5,secondary:4,tertiary:3,unclassified:2,residential:2,living_street:1}[r.type]||1);
export function createIntersectionScenery(scene,network,rules,{clear=()=>true}={}){
 const plans=[],seen=new Set(),limit=160,root=new T.Group();root.name='Intersection controls';scene.add(root);
 for(const [id,j]of rules.junctions)for(const e of j.entries){const dx=(e.to.x-e.from.x)/e.length,dz=(e.to.y-e.from.y)/e.length,mode=rules.controlFor(j,e);let kind=mode==='signal'?'signal':mode==='stop'?'stop':mode==='give_way'?'give_way':null;
  if(!kind&&j.branches>=3){const through=j.group.entries.some(other=>other!==e&&((other.from.x-other.to.x)/other.length*dx+(other.from.y-other.to.y)/other.length*dz)>.8),major=Math.max(...j.group.entries.map(o=>priority(o.r)));if(priority(e.r)<major||!through||e.r.tags.junction!=='roundabout'&&j.group.entries.some(o=>o.r.tags.junction==='roundabout'))kind='give_way'}if(!kind)continue;
  const key=j.group.id+':'+Math.round(Math.atan2(dx,dz)*4)+':'+kind;if(seen.has(key))continue;seen.add(key);const back=j.group.radius+1,off=e.r.width/2+.65,x=e.to.x-dx*back+dz*off,z=e.to.y-dz*back-dx*off,y=network.height(e.r,e.i,e.reverse?0:1,x,z);if(!clear(x,z,y+2))continue;const hit=network.at?.(x,z);if(hit&&hit.d<hit.r.width/2+.25&&Math.abs(network.height(hit.r,hit.i,hit.t,x,z)-y)<2)continue;plans.push({kind,x,z,y,dx,dz,yaw:Math.atan2(-dx,-dz),group:j.group,edge:e,line:{x:e.to.x-dx*back+dz*e.r.width*.23,z:e.to.y-dz*back-dx*e.r.width*.23,width:e.r.width*.44}})
 }
 const cells=new Map();for(const p of plans){const key=Math.floor(p.x/32)+','+Math.floor(p.z/32);if(!cells.has(key))cells.set(key,[]);cells.get(key).push(p)}
 const materials={pole:new T.MeshLambertMaterial({color:'#8f9691'}),red:new T.MeshLambertMaterial({color:'#b72023',side:T.DoubleSide}),white:new T.MeshLambertMaterial({color:'#e5e2d4',side:T.DoubleSide}),black:new T.MeshLambertMaterial({color:'#202621'}),lamp:new T.MeshBasicMaterial({color:'#ffffff'})};
 function label(text,background){if(typeof document==='undefined')return null;const c=document.createElement('canvas');c.width=c.height=256;const p=c.getContext('2d');p.fillStyle=background;p.fillRect(0,0,256,256);p.fillStyle=text==='STOP'?'white':'#20221e';p.font='bold '+(text==='STOP'?68:46)+'px Arial';p.textAlign='center';p.textBaseline='middle';if(text==='STOP')p.fillText(text,128,132,230);else{p.fillText('GIVE',128,102);p.fillText('WAY',128,153)}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t}
 const stopMaterial=new T.MeshLambertMaterial({map:label('STOP','#b72023'),color:typeof document==='undefined'?'#b72023':'white',side:T.DoubleSide}),giveMaterial=new T.MeshLambertMaterial({map:label('GIVE WAY','white'),color:typeof document==='undefined'?'#e5e2d4':'white',side:T.DoubleSide});
 const meshes={};function batch(name,geometry,material,count=limit){const mesh=new T.InstancedMesh(geometry,material,count);mesh.count=0;mesh.frustumCulled=false;mesh.name='Traffic '+name;root.add(mesh);meshes[name]=mesh;return mesh}
 batch('poles',new T.CylinderGeometry(.045,.06,1,7),materials.pole);batch('stop borders',new T.CircleGeometry(.48,8).rotateZ(Math.PI/8),materials.white);batch('stop faces',new T.CircleGeometry(.435,8).rotateZ(Math.PI/8),stopMaterial);batch('yield borders',new T.CircleGeometry(.54,3).rotateZ(-Math.PI/2),materials.red);batch('yield faces',new T.CircleGeometry(.435,3).rotateZ(-Math.PI/2),giveMaterial);batch('signal heads',new T.BoxGeometry(.36,1.05,.24),materials.black);for(const c of ['red','amber','green']){const m=new T.MeshBasicMaterial({color:{red:'#ff281a',amber:'#ffb51b',green:'#20e859'}[c],side:T.DoubleSide,fog:false,toneMapped:false,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-2});const mesh=batch(c+' signals',new T.CircleGeometry(.12,20),m);mesh.renderOrder=2;}batch('stop lines',new T.BoxGeometry(1,.018,.25),materials.white);batch('zebra stripes',new T.BoxGeometry(.42,.014,3.2),materials.white,640);
 const dummy=new T.Object3D(),color=new T.Color(),fallQuaternion=new T.Quaternion(),fallAxis=new T.Vector3(),fallPosition=new T.Vector3();function put(name,p,x,y,z,sx=1,sy=1,sz=1,tint){const mesh=meshes[name],i=mesh.count;if(i>=mesh.instanceMatrix.count)return;mesh.count++;dummy.position.set(x,y,z);dummy.rotation.set(0,p.yaw||0,0);dummy.scale.set(sx,sy,sz);if(p.brokenAt!==undefined&&name!=='stop lines'){const t=T.MathUtils.smoothstep(rules.clock-p.brokenAt,0,.65);fallAxis.set(p.fallZ,0,-p.fallX).normalize();fallQuaternion.setFromAxisAngle(fallAxis,t*1.53);fallPosition.set(x-p.x,y-p.y,z-p.z).applyQuaternion(fallQuaternion);dummy.position.set(p.x+fallPosition.x,p.y+.05+fallPosition.y,p.z+fallPosition.z);dummy.quaternion.premultiply(fallQuaternion)}dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);if(tint)mesh.setColorAt(i,color.set(tint))}
 let next=-1;function update(camera){if(rules.clock<next&&!plans.some(p=>p.brokenAt!==undefined&&rules.clock-p.brokenAt<.8))return;next=rules.clock+.12;for(const m of Object.values(meshes))m.count=0;for(const p of plans.filter(p=>Math.hypot(p.x-camera.x,p.z-camera.z)<700).sort((a,b)=>Math.hypot(a.x-camera.x,a.z-camera.z)-Math.hypot(b.x-camera.x,b.z-camera.z)).slice(0,limit)){
  const signal=p.kind==='signal';put('poles',p,p.x,p.y+(signal?1.85:1.2),p.z,1,signal?3.7:2.4,1);if(signal){put('signal heads',p,p.x,p.y+3.5,p.z);const phase=rules.signalFor(p.group,p.edge);for(const [i,c]of ['red','amber','green'].entries()){if(phase===c)put(c+' signals',p,p.x+Math.sin(p.yaw)*.14,p.y+3.81-i*.31,p.z+Math.cos(p.yaw)*.14)}}else{put(p.kind==='stop'?'stop borders':'yield borders',p,p.x,p.y+2.1,p.z);put(p.kind==='stop'?'stop faces':'yield faces',p,p.x+Math.sin(p.yaw)*.012,p.y+2.1,p.z+Math.cos(p.yaw)*.012)}put('stop lines',p,p.line.x,p.y+.065,p.line.z,p.line.width)}
  for(const c of rules.crossings)if(c.kind!=='signal'&&Math.hypot(c.x-camera.x,c.z-camera.z)<700){const p={yaw:Math.atan2(-c.dx,-c.dz)};for(let side=-c.width/2+.5;side<c.width/2;side+=.82)put('zebra stripes',p,c.x+c.dz*side,c.y+.075,c.z-c.dx*side)}for(const m of Object.values(meshes)){m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true}}
 return{plans,meshes,update,impact(car,from,to){let broken=0;const m=car.model||{},speed=Math.abs(car.velocity||0),yaw=car.yaw||0,reach=(m.length||4.5)/2+1;for(let ix=Math.floor((to.x-reach)/32);ix<=Math.floor((to.x+reach)/32);ix++)for(let iz=Math.floor((to.z-reach)/32);iz<=Math.floor((to.z+reach)/32);iz++)for(const p of cells.get(ix+','+iz)||[]){if(p.brokenAt!==undefined||Math.abs(from.y-p.y)>2||speed<(p.kind==='signal'?6:1.8))continue;const hit=[from,to].some(q=>{const x=p.x-q.x,z=p.z-q.z;return Math.abs(x*Math.cos(yaw)-z*Math.sin(yaw))<(m.width||1.8)/2+.14&&Math.abs(x*Math.sin(yaw)+z*Math.cos(yaw))<(m.length||4.5)/2+.18});if(!hit)continue;p.brokenAt=rules.clock;p.fallX=-Math.sin(yaw)*Math.sign(car.velocity);p.fallZ=-Math.cos(yaw)*Math.sign(car.velocity);car.velocity*=p.kind==='signal'?.72:.94;car.signImpacts=(car.signImpacts||0)+1;broken++}if(broken)next=-1;return broken},free(x,z,y){for(let ix=-1;ix<=1;ix++)for(let iz=-1;iz<=1;iz++)for(const p of cells.get((Math.floor(x/32)+ix)+','+(Math.floor(z/32)+iz))||[])if(p.brokenAt===undefined&&(y===undefined||Math.abs(y-2-p.y)<3)&&Math.hypot(x-p.x,z-p.z)<.16)return false;return true},get stats(){return{signs:plans.filter(p=>p.kind!=='signal').length,signals:plans.filter(p=>p.kind==='signal').length}}};
}
